import functools,http.server,json,pathlib,threading
from playwright.sync_api import sync_playwright,expect
root=pathlib.Path.cwd();server=http.server.ThreadingHTTPServer(('127.0.0.1',4188),functools.partial(http.server.SimpleHTTPRequestHandler,directory=str(root/'out')));threading.Thread(target=server.serve_forever,daemon=True).start()
try:
 with sync_playwright() as p:
  b=p.chromium.launch(executable_path='/opt/google/chrome/chrome',headless=True,args=['--no-sandbox'])
  for lang in ['en','ar']:
   page=b.new_page(viewport={'width':390,'height':1100});page.clock.install();page.add_init_script("window.__deny=true;const original=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(window.__deny&&k.includes('henglish_arcade_v1'))throw new DOMException('quota','QuotaExceededError');return original.call(this,k,v)}");t=json.load(open('src/i18n/locales/'+lang+'.json'));page.goto('http://127.0.0.1:4188/?lang='+lang+'#games');page.get_by_role('heading',name=t['ah.gameWordSprint'],exact=True).locator('..').get_by_role('button',name=t['ah.playNow'],exact=True).click();page.get_by_role('button',name=t['as.start'],exact=True).click();page.clock.run_for(61000);warning=page.get_by_role('status').filter(has_text=t['ap.storageError']);expect(warning).to_be_visible();assert page.evaluate("localStorage.getItem('henglish_arcade_v1:guest')") is None;warning.scroll_into_view_if_needed();page.screenshot(path='/downloads/arcade-save-warning-'+lang+'.png');retry=warning.get_by_role('button',name=t['to.retry'],exact=True);retry.click();expect(warning).to_be_visible();page.evaluate('window.__deny=false');retry.click();expect(warning).to_have_count(0);saved=page.evaluate("JSON.parse(localStorage.getItem('henglish_arcade_v1:guest'))");assert saved['totalPlays']==1 and saved['xp']==20 and len(saved['history'])==1;page.reload();expect(page.get_by_role('status').filter(has_text=t['ap.storageError'])).to_have_count(0);saved2=page.evaluate("JSON.parse(localStorage.getItem('henglish_arcade_v1:guest'))");assert saved2==saved;assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.close();print(lang,'Next arcade failedwritewarning,sessionkept,retryfailure,retrysuccess,no duplicateaward,persistedreload,width PASS')
  b.close()
finally:server.shutdown();server.server_close()
